__NUXT_JSONP__("/tr/promo_material/thanks", (function(a,b){return {data:[{details:{slug:"tr",pageTitle:"Promo - Broşürü İndirdiğiniz için Teşekkurler | Mentor Language Institute",pageDescription:b,title:"Promo - Broşürü İndirdiğiniz için Teşekkurler",subtitle:[b,"Lütfen aşağıdaki linkleri kullanarak broşürü indirin."],brochures:[{title:"2022 Hoş Geldiniz Promosyonu",image:"\u002Fimages\u002Fmaterial\u002F1643329809-WELCOME_Promotion_TURKISH_JAN13.jpg",link_text:a,link:"\u002Fassets\u002Fimages\u002Fmaterial\u002F1643329809-WELCOME_Promotion_TURKISH_JAN13.jpg"},{title:"MLI Broşürü ve Program Çizelgesi",image:"\u002Fimages\u002Fmaterial\u002Fmli-brochure-program-schedule-tr.jpg",link_text:a,link:"\u002Fdocuments\u002Fbrochure\u002FMLI School Brochure.pdf"},{title:"Konut Broşürü",image:"\u002Fimages\u002Fmaterial\u002F2022-housing-brochure.png",link_text:a,link:"\u002Fdocuments\u002Fbrochure\u002FUSSS Student Housing Brochure(updated 10.16.2024).pdf"},{title:"2026 Fiyat ve Kayıt Paketi",image:"\u002Fimages\u002Fmaterial\u002F2026-price-package.PNG",link_text:a,link:"\u002Fdocuments\u002Fbrochure\u002F2026 MLI Info Pack updated_9.17.25.pdf"},{title:"MLI Etkinlik Broşürü",image:"\u002Fimages\u002Fmaterial\u002F2027 MLI Activity.PNG",link_text:a,link:"\u002Fdocuments\u002Fbrochure\u002F2027 MLI Activity Calendar Brochure 10.1.26.pdf"}],other_info:["\u003Cspan class='hutoaka'\u003EBir kabul personeli, sorgunuzla ilgili olarak size e-posta gönderecektir.\u003C\u002Fspan\u003E\u003Cbr \u002F\u003EÖğrenci vizeleri, barınma durumu veya başka herhangi bir konuda herhangi bir sorunuz varsa, lütfen istediğiniz zaman bizimle iletişime geçmekten çekinmeyin.","Amerika Birleşik Devletleri'nde yurtdışında eğitim alma süreci çok karmaşıktır, prosedürlerde size telefonda rehberlik edebiliriz.","\"Bana telefonla ulaşma\" seçeneğini işaretlemediyseniz, sizi bir veya iki gün içinde arayacağız.","\u003Cb\u003E【WESTWOOD KAMPÜSÜ】\u003C\u002Fb\u003E\u003Cbr \u002F\u003E10880 Wilshire Blvd., Suite 122\u003Cbr \u002F\u003ELos Angeles, CA 90024\u003Cbr \u002F\u003ETEL: ＋1（310）887-0777\u003Cbr \u002F\u003EE-mail: info@mliesl.edu\u003Cbr \u002F\u003EÇalışma saatleri: Pazartesiden Perşembeye 8:30 – 20:30, Cuma 8:30 – 18:00","\u003Cb\u003E【HOLLYWOOD KAMPÜSÜ】\u003C\u002Fb\u003E\u003Cbr \u002F\u003E7080 Hollywood Blvd., Suite 314\u003Cbr \u002F\u003ELos Angeles, CA 90028\u003Cbr \u002F\u003ETEL: ＋1（323）870-7102\u003Cbr \u002F\u003EE-mail: hollywood@mliesl.edu\u003Cbr \u002F\u003EÇalışma saatleri: Pazartesiden Cumaya 8:30 – 17:00"],dir:"\u002Fpromo-material-thanks",path:"\u002Fpromo-material-thanks\u002Ftr",extension:".json",createdAt:"2026-10-22T16:31:30.792Z",updatedAt:"2026-10-06T17:46:57.898Z"}}],fetch:{},mutations:void 0}}("\u003Ci class='bi bi-arrow-right'\u003E\u003C\u002Fi\u003E İndir","Okul broşürümüz ve bilgi paketimizi indirme isteğiniz için teşekkür ederiz.")));